const body = $input.first().json;
const record = body.record ?? body;
const stage = String(record.stage ?? '');
const proposalStages = ['Proposal Sent', 'PROPOSAL', 'PROPOSAL_SENT'];
const isProposalSent = proposalStages.includes(stage);

const name = record.name ?? 'Untitled deal';
const companyName =
  record.company?.name ?? record.companyName ?? record.companyId ?? '';
const amountObject = record.amount ?? {};
const amount =
  typeof amountObject.amountMicros === 'number'
    ? `${(amountObject.amountMicros / 1000000).toFixed(2)} ${amountObject.currencyCode ?? ''}`.trim()
    : String(record.amount ?? '');

const teamsPayload = {
  type: 'message',
  attachments: [
    {
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: {
        $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard',
        version: '1.4',
        body: [
          {
            type: 'TextBlock',
            text: '🎯 Proposal Sent',
            weight: 'Bolder',
            size: 'Medium',
            color: 'Accent',
          },
          {
            type: 'FactSet',
            facts: [
              { title: 'Deal', value: String(name) },
              { title: 'Company', value: String(companyName) },
              { title: 'Value', value: String(amount) },
            ],
          },
        ],
      },
    },
  ],
};

return [
  {
    json: {
      name,
      companyName,
      amount,
      stage,
      isProposalSent,
      opportunityId: record.id ?? null,
      teamsPayload,
    },
  },
];
